using System.Collections.Generic;

/// <summary>
/// Teacher Rachel's stress score (RawStressAnalyzer: how far the word's
/// stressed syllable stands out, positive when it is the most prominent) for
/// each stress-checked word, measured from her recordings: as she said it, and with the stress
/// moved to the other syllable. The same idea as StressReferences, for the
/// raw-audio check; see there for what "enforced" means.
///
/// The numbers live in RawStressReferenceData.cs, GENERATED by
/// Tools > SALINLAHI > Rebuild Stress References (or
/// Tools/test_stress_rules.sh generate). For the raw check each recording is
/// measured as a phone microphone might hear it - with room noise at three
/// levels, and with the voice raised in pitch the way a child's is - and a
/// word is only enforced when her own recording passes under every one of
/// those and the moved one fails under all but one.
/// </summary>
public static partial class RawStressReferences
{
    private static Dictionary<string, StressReferences.Entry> table;

    public static StressReferences.Entry For(StressPattern pattern)
    {
        if (table == null)
        {
            Dictionary<string, StressReferences.Entry> t =
                new Dictionary<string, StressReferences.Entry>(System.StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < Rows.Length; i++)
                t[Rows[i].word] = new StressReferences.Entry
                {
                    reference = Rows[i].reference,
                    moved = Rows[i].moved,
                    enforced = Rows[i].enforced,
                    measured = true,
                };
            table = t;
        }

        StressReferences.Entry e;
        if (pattern != null && table.TryGetValue(pattern.Word, out e)) return e;

        // No recording to calibrate against: the natural line - the stressed
        // syllable being the most prominent one - and never enforced.
        e = new StressReferences.Entry();
        e.reference = 0.5f;
        e.moved = -0.5f;
        e.enforced = false;
        e.measured = false;
        return e;
    }

    private struct Row
    {
        public string word;
        public float reference;
        public float moved;
        public bool enforced;

        public Row(string word, float reference, float moved, bool enforced)
        {
            this.word = word;
            this.reference = reference;
            this.moved = moved;
            this.enforced = enforced;
        }
    }
}
